const root=document.getElementById("app");const A=()=>window.go?.main?.App;let state={step:"prerequisites",theme:"windows"};let error="";function call(name,...args){const api=A();if(!api||!api[name])return Promise.reject(new Error("Backend bindings are unavailable. Run with Wails."));return api[name](...args)}function setError(e){error=e?.message||String(e);render()}async function boot(){try{state=await call("State")}catch(e){}render()}function render(){root.innerHTML=layout();bind()}function layout(){return `<div class="shell"><aside class="sidebar"><div class="brand">Git Tool</div><div class="sub">Secure Git setup</div><nav class="nav"><button class="active">Setup</button><button onclick="settings()">Settings</button></nav><div style="margin-top:40px" class="muted">Theme: ${state.theme}</div></aside><main class="content">${screen()}</main></div>`}function screen(){if(state.step==="prerequisites")return prereq();if(state.step==="git")return git();if(state.step==="ssh")return ssh();if(state.step==="agent")return agent();if(state.step==="github")return github();if(state.step==="signing")return signing();return complete()}function header(title,desc){return `<div class="title">${title}</div><p class="muted">${desc}</p>`}function prereq(){return header("Welcome to Git Tool","Set up Git, SSH and GitHub securely on this computer.")+`<div class="card" style="margin-top:28px"><h3>Before we begin</h3><p class="muted">Git and OpenSSH are required. No private key is uploaded or stored by this application.</p><button class="btn" onclick="next('CheckPrerequisites')">Start setup</button>${error?'<div class="error">'+error+'</div>':''}</div><div class="grid"><div class="card theme ${state.theme==='dark'?'selected':''}" onclick="theme('dark')"><h3>Git Tool Dark</h3><p class="muted">Modern dark workspace</p><div class="preview dark">Secure setup · verified</div></div><div class="card theme ${state.theme==='windows'?'selected':''}" onclick="theme('windows')"><h3>Windows Native</h3><p class="muted">Light Windows-style interface</p><div class="preview win">Secure setup · ✓ verified</div></div></div>`}function git(){return header("Git identity","Configure the name and email Git uses for commits.")+`<div class="card" style="margin-top:28px"><div class="field"><label>Name</label><input id="name" placeholder="John Doe"></div><div class="field"><label>Email</label><input id="email" placeholder="john@example.com"></div><label><input id="global" type="checkbox" checked> Use global Git configuration</label><div class="actions"><button class="btn" onclick="configureGit()">Continue</button></div>${error?'<div class="error">'+error+'</div>':''}</div>`}function ssh(){return header("SSH key","Select an existing key or generate a new Ed25519 key.")+`<div class="card" style="margin-top:28px"><p class="muted">Default key: ~/.ssh/id_ed25519</p><label><input id="overwrite" type="checkbox"> Replace the default key if it exists</label><div class="field"><label>New key passphrase (optional)</label><input id="pass" type="password" autocomplete="new-password"></div><div class="actions"><button class="btn" onclick="generate()">Generate / use key</button></div>${error?'<div class="error">'+error+'</div>':''}</div>`}function agent(){return header("SSH agent","Load the exact selected key into the SSH agent.")+`<div class="card" style="margin-top:28px"><p>Key: <span class="muted">${state.keyPath||"selected key"}</span></p><button class="btn" onclick="next('SetupSSHAgent')">Configure agent</button>${error?'<div class="error">'+error+'</div>':''}</div>`}function github(){return header("GitHub","Add the public key to GitHub, then verify the connection.")+`<div class="card" style="margin-top:28px"><button class="btn" onclick="copyKey()">Copy public key</button><button class="btn" style="margin-left:8px" onclick="openGitHub()">Open GitHub</button><pre id="key" style="white-space:pre-wrap;margin-top:20px"></pre><button class="btn" onclick="next('VerifyGitHubSSH')">Verify SSH connection</button>${error?'<div class="error">'+error+'</div>':''}</div>`}function signing(){return header("Signing","SSH commit/tag signing is optional.")+`<div class="card" style="margin-top:28px"><p class="muted">Enable this only if you want Git commits and tags signed with your SSH key.</p><button class="btn" onclick="next('ConfigureSigning',true)">Enable signing</button><button class="btn" style="margin-left:8px;background:#21262d" onclick="next('ConfigureSigning',false)">Skip signing</button>${error?'<div class="error">'+error+'</div>':''}</div>`}function complete(){return header("Your Git environment is ready","All required checks passed.")+`<div class="card" style="margin-top:28px"><div class="status"><span>Git identity</span><span class="success">✓ Verified</span></div><div class="status"><span>SSH key</span><span class="success">✓ Configured</span></div><div class="status"><span>SSH agent</span><span class="success">✓ Verified</span></div><div class="status"><span>GitHub</span><span class="success">✓ Authenticated</span></div><div class="status"><span>Signing</span><span>${state.signing?'✓ Enabled':'Optional'}</span></div></div>`}async function next(name,...args){error="";try{await call(name,...args);state=await call("State");render()}catch(e){setError(e)}}async function configureGit(){await next("ConfigureGit",document.getElementById("name").value,document.getElementById("email").value,document.getElementById("global").checked)}async function generate(){await next("GenerateSSHKey",document.getElementById("pass").value,document.getElementById("overwrite").checked)}async function copyKey(){try{document.getElementById("key").textContent=await call("GitHubPublicKey")}catch(e){setError(e)}}async function openGitHub(){call("OpenGitHubSSHSettings")}async function theme(v){try{await call("SetTheme",v);state=await call("State");render()}catch(e){setError(e)}}function settings(){alert("Theme can be changed from the cards on the setup screen.")}boot();